									<p style="text-align:center;font-family:Space Grotesk,sans-serif;font-weight:700;font-size:12.5px;letter-spacing:2px;text-transform:uppercase;color:#7C3AED;margin:0"><span style="display:inline-block;width:22px;height:3px;background:linear-gradient(100deg,#FF2E7E,#7C3AED);border-radius:2px;margin-right:8px;vertical-align:middle"></span>The difference, in one table</p>								</div>
				<div class="elementor-element elementor-element-45c505ef elementor-widget elementor-widget-heading" data-id="45c505ef" data-element_type="widget" data-e-type="widget" data-widget_type="heading.default">
					<h2 class="elementor-heading-title elementor-size-default">Glowth vs. a <span class="hl">generic beauty marketing agency</span></h2>				</div>
				<div class="elementor-element elementor-element-5a03ea9 elementor-widget elementor-widget-html" data-id="5a03ea9" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
					 
    
